  getGetAssessmentQueryKey, getGetContentQueryKey, getGetEidPairQueryKey, getGetFollowupQueryKey, getGetServiceQueryKey,
  getListFollowupsQueryKey, getListReferralsQueryKey,
  useCompleteEidMilestone, useCompleteFollowup, useCreateAssessment, useCreateFollowup, useCreateReferral, useCreateSafeguardingReport,
  useCreateStaffUser, useCreateSupportRequest, useGetAssessment, useGetAudit, useGetContent, useGetCurrentUser, useGetDashboardSummary, useGetEidPair,
  useGetFollowup, useGetReports, useGetService, useListCases, useListContent, useListEidPairs, useListFollowups, useListReferrals,
