const cx = (...values: Array<string | false | undefined>) => values.filter(Boolean).join(' ');
const formatDate = (value?: string) => value ? new Date(value).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }) : '—';

export function LoadingState({ label = 'Loading your workspace' }: { label?: string }) {
  return <div className="space-y-3 py-10" data-testid="state-loading"><div className="h-4 w-40 animate-pulse rounded bg-[hsl(var(--muted))]" /><div className="h-20 animate-pulse rounded-2xl bg-[hsl(var(--muted))]" /><p className="mono text-xs text-[hsl(var(--muted-foreground))]">{label}</p></div>;
}
export function ErrorState({ message = 'Something went quiet. Please try again.' }: { message?: string }) {
  return <div className="rounded-2xl border border-[hsl(var(--destructive)/.35)] bg-[hsl(var(--destructive)/.06)] p-6" data-testid="state-error"><p className="font-medium text-[hsl(var(--destructive))]">We could not load this yet</p><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{message}</p><button data-testid="button-retry" onClick={() => window.location.reload()} className="mt-4 rounded-lg bg-[hsl(var(--destructive))] px-3 py-2 text-sm text-white">Try again</button></div>;
}
export function EmptyState({ title, body, action }: { title: string; body: string; action?: ReactNode }) {
  return <div className="rounded-2xl border border-dashed border-[hsl(var(--border))] bg-[hsl(var(--card)/.65)] p-10 text-center" data-testid="state-empty"><div className="mx-auto mb-4 grid h-11 w-11 place-items-center rounded-full bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Sparkles className="h-5 w-5" /></div><p className="font-medium">{title}</p><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-[hsl(var(--muted-foreground))]">{body}</p>{action && <div className="mt-5">{action}</div>}</div>;
}
function Frame({ children, eyebrow, title, description, action, className }: { children: ReactNode; eyebrow?: string; title: string; description?: string; action?: ReactNode; className?: string }) {
  return <div className={cx('page-in mx-auto max-w-7xl px-5 py-8 lg:px-10 lg:py-12', className)}><div className="mb-9 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="mono mb-3 text-[10px] uppercase tracking-[.22em] text-[hsl(var(--primary)/.72)]">{eyebrow}</p><h1 className="display-font max-w-3xl text-4xl leading-[1.08] tracking-[-.035em] text-[hsl(var(--primary))] md:text-5xl">{title}</h1>{description && <p className="mt-4 max-w-2xl text-base leading-7 text-[hsl(var(--muted-foreground))]">{description}</p>}</div>{action}</div>{children}</div>;
}
function Button({ children, onClick, href, variant = 'primary', disabled = false, type = 'button', testId = 'button-action' }: { children: ReactNode; onClick?: () => void; href?: string; variant?: 'primary' | 'secondary' | 'quiet' | 'danger'; disabled?: boolean; type?: 'button' | 'submit'; testId?: string }) {
  const cls = cx('inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold transition-transform hover:-translate-y-px disabled:cursor-not-allowed disabled:opacity-50', variant === 'primary' && 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] shadow-sm', variant === 'secondary' && 'bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))]', variant === 'quiet' && 'text-[hsl(var(--primary))] hover:bg-[hsl(var(--secondary))]', variant === 'danger' && 'bg-[hsl(var(--destructive))] text-white');
  if (href) return <Link href={href} data-testid={testId} className={cls}>{children}</Link>;
  return <button type={type} onClick={onClick} disabled={disabled} data-testid={testId} className={cls}>{children}</button>;
}
function Pill({ children, tone = 'neutral' }: { children: ReactNode; tone?: 'neutral' | 'good' | 'warn' | 'risk' }) {
  return <span className={cx('inline-flex rounded-full px-2.5 py-1 text-[11px] font-semibold', tone === 'neutral' && 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]', tone === 'good' && 'bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]', tone === 'warn' && 'bg-[hsl(var(--accent)/.32)] text-[hsl(var(--foreground))]', tone === 'risk' && 'bg-[hsl(var(--destructive)/.12)] text-[hsl(var(--destructive))]')}>{children}</span>;
}
function Card({ children, className = '' }: { children: ReactNode; className?: string }) { return <div className={cx('rounded-2xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] shadow-[var(--shadow-xs)]', className)}>{children}</div>; }
function Input({ label, name, value, onChange, placeholder, type = 'text', required = false }: { label: string; name: string; value: string; onChange: (value: string) => void; placeholder?: string; type?: string; required?: boolean }) {
  return <label className="block text-sm font-medium"><span className="mb-2 block text-[hsl(var(--foreground))]">{label}</span><input data-testid={`input-${name}`} name={name} type={type} value={value} required={required} placeholder={placeholder} onChange={e => onChange(e.target.value)} className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3.5 py-3 text-sm outline-none transition focus:border-[hsl(var(--ring))] focus:ring-2 focus:ring-[hsl(var(--ring)/.18)]" /></label>;
}

export function HomePage() {
  const health = useHealthCheck();
  return <AppShell><main>
    <section className="relative overflow-hidden border-b border-[hsl(var(--border))] bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]"><div className="soft-grid absolute inset-0 opacity-10" /><div className="relative mx-auto grid max-w-7xl gap-12 px-5 py-20 lg:grid-cols-[1.05fr_.95fr] lg:px-10 lg:py-28"><div className="rise-in"><p className="mono mb-6 text-[11px] uppercase tracking-[.25em] text-[hsl(var(--sidebar-primary))]">A quieter way to find a next step</p><h1 className="display-font max-w-3xl text-5xl leading-[.98] tracking-[-.05em] md:text-7xl">You do not have to work it out alone.</h1><p className="mt-7 max-w-xl text-lg leading-8 text-[hsl(var(--primary-foreground)/.72)]">Y-Connect helps young people find trusted local services, understand what they are feeling, and reach a real person when that is what would help.</p><div className="mt-9 flex flex-wrap gap-3"><Button href="/assess" testId="button-home-assess">Take a private self-check <ArrowRight className="h-4 w-4" /></Button><Button href="/directory" variant="quiet" testId="button-home-directory">Explore services</Button></div></div><div className="rise-in delay-2 flex items-end"><div className="relative ml-auto w-full max-w-md"><div className="absolute -right-5 -top-5 h-24 w-24 rounded-full border border-[hsl(var(--sidebar-primary)/.35)]" /><Card className="relative overflow-hidden border-[hsl(var(--sidebar-border))] bg-[hsl(var(--sidebar-accent)/.75)] p-6 text-[hsl(var(--sidebar-foreground))]"><div className="mb-12 flex items-center justify-between"><span className="mono text-[10px] uppercase tracking-[.2em] text-[hsl(var(--sidebar-primary))]">Your starting point</span><span className="h-2 w-2 rounded-full bg-[hsl(var(--sidebar-primary))]" /></div><p className="display-font text-3xl">Small steps count.</p><p className="mt-3 text-sm leading-6 text-[hsl(var(--sidebar-foreground)/.7)]">Start with what feels manageable. Nothing here is a diagnosis, and you can leave at any time.</p><div className="mt-8 border-t border-[hsl(var(--sidebar-border))] pt-5 text-xs text-[hsl(var(--sidebar-foreground)/.65)]"><LockKeyhole className="mr-2 inline h-3.5 w-3.5" />No account needed to browse</div></Card></div></div></div></section>
    <section className="mx-auto max-w-7xl px-5 py-16 lg:px-10"><div className="grid gap-5 md:grid-cols-3"><Card className="rise-in p-6"><span className="mono text-xs text-[hsl(var(--primary)/.62)]">01 / Find your footing</span><h2 className="display-font mt-8 text-2xl">A private self-check</h2><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">A short, deterministic reflection that points to useful support without labelling you.</p><Link href="/assess" data-testid="link-home-assess" className="mt-7 inline-flex items-center gap-2 text-sm font-semibold text-[hsl(var(--primary))]">Begin <ArrowRight className="h-4 w-4" /></Link></Card><Card className="rise-in delay-1 bg-[hsl(var(--secondary)/.55)] p-6"><span className="mono text-xs text-[hsl(var(--primary)/.62)]">02 / Look around</span><h2 className="display-font mt-8 text-2xl">Services that make sense</h2><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Search by place and need, with practical details for deciding what comes next.</p><Link href="/directory" data-testid="link-home-directory" className="mt-7 inline-flex items-center gap-2 text-sm font-semibold text-[hsl(var(--primary))]">Open directory <ArrowRight className="h-4 w-4" /></Link></Card><Card className="rise-in delay-2 p-6"><span className="mono text-xs text-[hsl(var(--primary)/.62)]">03 / Talk to a human</span><h2 className="display-font mt-8 text-2xl">Support, on your terms</h2><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Ask for a role, a contact method, or simply a person who can listen.</p><Link href="/connect" data-testid="link-home-connect" className="mt-7 inline-flex items-center gap-2 text-sm font-semibold text-[hsl(var(--primary))]">Request support <ArrowRight className="h-4 w-4" /></Link></Card></div></section>
    <section className="mx-auto max-w-7xl px-5 pb-20 lg:px-10"><div className="rounded-3xl bg-[hsl(var(--accent)/.38)] p-8 md:flex md:items-center md:justify-between md:p-12"><div><p className="mono text-[10px] uppercase tracking-[.2em]">Need to know</p><h2 className="display-font mt-3 text-3xl text-[hsl(var(--primary))]">Your choices are yours.</h2><p className="mt-3 max-w-xl text-sm leading-6 text-[hsl(var(--foreground)/.72)]">Learn how confidentiality, consent, and safeguarding work before you decide to connect.</p></div><Button href="/rights" variant="secondary" testId="button-home-rights">Read your rights <ChevronRight className="h-4 w-4" /></Button></div></section>
  </main></AppShell>;
}

export function LearnPage() {
  const { data, isLoading, isError } = useListContent();
  const [category, setCategory] = useState('all');
  const items = (data ?? []) as ContentItem[];
  const filtered = items.filter(item => category === 'all' || item.category === category);
  const categories = ['all', ...Array.from(new Set(items.map(item => item.category)))];
  return <AppShell><Frame eyebrow="Learning library" title="Information that meets you where you are." description="Short, clear resources for questions that can be hard to say out loud. Read at your own pace.">
    <div className="mb-7 flex flex-wrap gap-2">{categories.map(item => <button key={item} data-testid={`button-category-${item}`} onClick={() => setCategory(item)} className={cx('rounded-full px-3.5 py-2 text-sm capitalize', category === item ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]' : 'bg-[hsl(var(--secondary))] text-[hsl(var(--muted-foreground))]')}>{item}</button>)}</div>
    {isLoading ? <LoadingState label="Finding useful reads" /> : isError ? <ErrorState /> : filtered.length === 0 ? <EmptyState title="Nothing in this shelf yet" body="Try another topic, or come back soon as the library grows." /> : <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{filtered.map((item, index) => <Link href={`/learn/${item.slug}`} key={item.id} data-testid={`card-content-${item.id}`} className={cx('group block rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-6 shadow-[var(--shadow-xs)] transition hover:-translate-y-1 hover:shadow-[var(--shadow)]', index === 0 && 'md:col-span-2 md:bg-[hsl(var(--primary))] md:text-[hsl(var(--primary-foreground))]')}><div className="flex items-start justify-between"><Pill tone={index === 0 ? 'warn' : 'good'}>{item.category}</Pill><span className="mono text-[10px] opacity-60">{item.duration}</span></div><h2 className="display-font mt-10 text-2xl tracking-tight">{item.title}</h2><p className="mt-3 text-sm leading-6 opacity-70">{item.excerpt}</p><div className="mt-8 flex items-center gap-2 text-sm font-semibold">Read resource <ArrowRight className="h-4 w-4 transition group-hover:translate-x-1" /></div></Link>)}</div>}
  </Frame></AppShell>;
}

export function ContentDetailPage() {
  const { slug = '' } = useParams<{ slug: string }>();
  const { data, isLoading, isError } = useGetContent(slug, { query: { enabled: Boolean(slug), queryKey: getGetContentQueryKey(slug) } });
  const body = data?.body ?? data?.excerpt ?? 'This resource is being prepared.';
  return <AppShell><Frame eyebrow="Learning library / resource" title={isLoading ? 'Opening resource…' : data?.title ?? 'Resource not found'} description={data?.excerpt}><div className="grid gap-8 lg:grid-cols-[1fr_300px]"><article className="prose prose-slate max-w-none rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-7 leading-8 md:p-10" data-testid="content-body">{isError ? <ErrorState /> : isLoading ? <LoadingState /> : body.split('\n').map((paragraph, index) => <p key={index}>{paragraph}</p>)}</article><aside className="h-fit rounded-2xl bg-[hsl(var(--secondary))] p-6"><p className="mono text-[10px] uppercase tracking-[.2em]">Keep exploring</p><p className="display-font mt-4 text-2xl">You set the pace.</p><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">You can return to the library whenever you need a different kind of support.</p><Button href="/connect" variant="primary" testId="button-content-connect" >Talk to someone</Button></aside></div></Frame></AppShell>;
}

export function AssessPage() {
  const create = useCreateAssessment();
  const questions = [
    { key: 'last_test', prompt: 'When was your last HIV test?' },
    { key: 'condomless_sex', prompt: 'In the last year, have you had sex without a condom when you did not want to take that chance?' },
    { key: 'forced_sex', prompt: 'Has anyone pressured or forced you into sexual contact?' },
  ];
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const options = [
    [{ label: 'I have never tested', value: 'never' }, { label: 'More than a year ago', value: 'over_year' }, { label: 'Within the last year', value: 'within_year' }, { label: 'Within the last 3 months', value: 'within_3m' }],
    [{ label: 'Yes', value: 'yes' }, { label: 'No', value: 'no' }, { label: 'Prefer not to say', value: 'no' }],
    [{ label: 'Yes', value: 'yes' }, { label: 'No', value: 'no' }, { label: 'Prefer not to say', value: 'no' }],
  ];
  const submit = () => create.mutate({ data: { answers } }, { onSuccess: result => { window.history.pushState({}, '', `/assess/result/${result.id}`); window.dispatchEvent(new PopStateEvent('popstate')); } });
  return <AppShell><Frame eyebrow={`Private self-check · 0${step + 1} / 03`} title="A few questions. No labels." description="Choose the answer that is nearest to your experience. There is no right answer, and you can stop whenever you want."><div className="mx-auto max-w-2xl"><div className="mb-10 flex gap-2">{questions.map((_, i) => <div key={i} className={cx('h-1.5 flex-1 rounded-full', i <= step ? 'bg-[hsl(var(--primary))]' : 'bg-[hsl(var(--muted))')} />)}</div><Card className="p-7 md:p-10"><p className="mono text-xs text-[hsl(var(--muted-foreground))]">QUESTION {step + 1}</p><h2 className="display-font mt-5 text-3xl text-[hsl(var(--primary))]">{questions[step].prompt}</h2><div className="mt-8 space-y-3">{options[step].map(option => <button key={option.value} data-testid={`button-answer-${option.value}`} onClick={() => setAnswers(prev => ({ ...prev, [questions[step].key]: option.value }))} className={cx('flex w-full items-center justify-between rounded-xl border p-4 text-left text-sm transition', answers[questions[step].key] === option.value ? 'border-[hsl(var(--primary))] bg-[hsl(var(--secondary))] font-semibold' : 'border-[hsl(var(--border))] hover:border-[hsl(var(--ring))]')}><span>{option.label}</span>{answers[questions[step].key] === option.value && <Check className="h-4 w-4 text-[hsl(var(--primary))]" />}</button>)}</div><div className="mt-10 flex justify-between"><Button variant="quiet" onClick={() => setStep(Math.max(0, step - 1))} testId="button-assess-back" disabled={step === 0}>Back</Button>{step < 2 ? <Button onClick={() => setStep(step + 1)} testId="button-assess-next" disabled={!answers[questions[step].key]}>Next <ArrowRight className="h-4 w-4" /></Button> : <Button onClick={submit} testId="button-assess-submit" disabled={!answers.forced_sex || create.isPending}>{create.isPending ? 'Scoring…' : 'See my next step'} <ArrowRight className="h-4 w-4" /></Button>}</div>{create.isError && <p className="mt-5 text-sm text-[hsl(var(--destructive))]">We could not score that just now. Your answers have not been saved.</p>}</Card><p className="mt-5 text-center text-xs text-[hsl(var(--muted-foreground))]">This is a reflection tool, not a clinical diagnosis.</p></div></Frame></AppShell>;
}

export function AssessmentResultPage() {
  const { id = '' } = useParams<{ id: string }>();
  const numericId = Number(id);
  const { data, isLoading, isError } = useGetAssessment(numericId, { query: { enabled: Boolean(numericId), queryKey: getGetAssessmentQueryKey(numericId) } });
  const result = data as AssessmentResult | undefined;
  return <AppShell><Frame eyebrow="Your reflection" title="Here is a possible next step." description="This is a gentle signpost based on the answers you gave, not a label. You know your experience best.">{isLoading ? <LoadingState /> : isError || !result ? <ErrorState message="That reflection could not be found." /> : <div className="grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><Card className="overflow-hidden"><div className="bg-[hsl(var(--primary))] p-8 text-[hsl(var(--primary-foreground))]"><p className="mono text-xs uppercase tracking-[.2em] text-[hsl(var(--sidebar-primary))]">Your pathway</p><p className="display-font mt-4 text-4xl">{result.pathway}</p><p className="mt-3 max-w-lg text-sm leading-6 opacity-75">Your responses suggest that a little connection could be useful right now.</p></div><div className="grid grid-cols-2 gap-4 p-7"><div><p className="mono text-[10px] uppercase text-[hsl(var(--muted-foreground))]">Reflection band</p><p className="mt-2 text-xl font-semibold">{result.band}</p></div><div><p className="mono text-[10px] uppercase text-[hsl(var(--muted-foreground))]">Total</p><p className="mt-2 text-xl font-semibold">{result.total}</p></div></div></Card><div className="space-y-4"><Card className="p-6"><div className="flex gap-3"><HeartHandshake className="mt-1 h-5 w-5 text-[hsl(var(--primary))]" /><div><h2 className="font-semibold">Choose what feels right</h2><p className="mt-2 text-sm leading-6 text-[hsl(var(--muted-foreground))]">You can read more, find a local service, or ask us to connect you with a person.</p><div className="mt-5 flex flex-wrap gap-2"><Button href="/connect" testId="button-result-connect">Request a person</Button><Button href="/directory" variant="secondary" testId="button-result-directory">Find a service</Button></div></div></div></Card>{(result.urgent || result.safeguardingFlag) && <Card className="border-[hsl(var(--destructive)/.35)] bg-[hsl(var(--destructive)/.05)] p-6"><div className="flex gap-3"><ShieldAlert className="mt-1 h-5 w-5 text-[hsl(var(--destructive))]" /><div><h2 className="font-semibold">You may need support sooner</h2><p className="mt-2 text-sm leading-6">If you feel in immediate danger, contact local emergency help. You can also make a confidential concern report.</p><Button href="/report-concern" variant="danger" testId="button-result-report">Make a confidential report</Button></div></div></Card>}</div></div>}</Frame></AppShell>;
}

export function DirectoryPage() {
  const [district, setDistrict] = useState('');
  const [service, setService] = useState('');
  const [selected, setSelected] = useState<number | null>(null);
  const { data, isLoading, isError } = useListServices({ district: district || undefined, service: service || undefined });
  const detail = useGetService(selected ?? 0, { query: { enabled: Boolean(selected), queryKey: getGetServiceQueryKey(selected ?? 0) } });
  const services = (data ?? []) as ServicePoint[];
  return <AppShell><Frame eyebrow="Service directory" title="Find somewhere that understands." description="Search trusted service points by district or the kind of help you are looking for."><div className="grid gap-7 lg:grid-cols-[280px_1fr]"><Card className="h-fit p-5"><p className="mono mb-4 text-[10px] uppercase tracking-[.2em]">Narrow the list</p><div className="space-y-4"><Input label="District" name="district" value={district} onChange={setDistrict} placeholder="e.g. Central" /><Input label="Service or need" name="service" value={service} onChange={setService} placeholder="e.g. counselling" /></div><div className="mt-6 flex items-center gap-2 text-xs leading-5 text-[hsl(var(--muted-foreground))]"><MapPin className="h-4 w-4 shrink-0" />Locations are synthetic for this prototype.</div></Card><div>{isLoading ? <LoadingState label="Mapping nearby support" /> : isError ? <ErrorState /> : services.length === 0 ? <EmptyState title="No services match yet" body="Try a broader district or search term." /> : <div className="grid gap-4 md:grid-cols-2">{services.map(item => <button onClick={() => setSelected(item.id)} data-testid={`card-service-${item.id}`} key={item.id} className="text-left"><Card className="h-full p-5 transition hover:-translate-y-0.5 hover:shadow-[var(--shadow)]"><div className="flex items-start justify-between gap-3"><div><p className="font-semibold">{item.name}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{item.type} · {item.district}</p></div><MapPin className="h-4 w-4 text-[hsl(var(--primary))]" /></div><p className="mt-5 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{item.services.join(' · ')}</p><div className="mt-5 flex items-center justify-between border-t border-[hsl(var(--border))] pt-4 text-xs"><span>{item.hours}</span><span className="font-semibold text-[hsl(var(--primary))]">View details <ArrowRight className="ml-1 inline h-3.5 w-3.5" /></span></div></Card></button>)}</div>}</div></div>{selected && <div className="fixed inset-0 z-50 grid place-items-center bg-[hsl(var(--primary)/.35)] p-5" onClick={() => setSelected(null)}><div className="w-full max-w-lg rounded-2xl bg-[hsl(var(--card))] p-7 shadow-[var(--shadow-xl)]" onClick={event => event.stopPropagation()}>{detail.isLoading ? <LoadingState /> : detail.data ? <><div className="flex items-start justify-between"><div><p className="mono text-[10px] uppercase tracking-[.2em]">Service point</p><h2 className="display-font mt-2 text-3xl">{detail.data.name}</h2></div><button data-testid="button-close-service" onClick={() => setSelected(null)}><X className="h-5 w-5" /></button></div><div className="mt-7 grid gap-4 text-sm"><p><MapPin className="mr-2 inline h-4 w-4 text-[hsl(var(--primary))]" />{detail.data.address}, {detail.data.district}</p><p><Clock3 className="mr-2 inline h-4 w-4 text-[hsl(var(--primary))]" />{detail.data.hours}</p><p><MessageCircle className="mr-2 inline h-4 w-4 text-[hsl(var(--primary))]" />{detail.data.phone}</p></div><div className="mt-7 flex gap-2"><Button href="/connect" testId="button-service-connect">Ask for support</Button><Button variant="secondary" onClick={() => setSelected(null)} testId="button-service-close">Done</Button></div></> : <ErrorState />}</div></div>}</Frame></AppShell>;
}

export function ConnectPage() {
  const create = useCreateSupportRequest();
  const [role, setRole] = useState('A youth worker');
  const [contact, setContact] = useState('Text message');
  const [message, setMessage] = useState('');
  const [sent, setSent] = useState(false);
  return <AppShell><Frame eyebrow="Human support" title="Ask for a person, in your own words." description="Tell us what kind of support would feel useful. You do not need to explain everything perfectly."><div className="grid gap-7 lg:grid-cols-[1fr_320px]"><Card className="p-7 md:p-9">{sent ? <div className="py-10 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Check className="h-6 w-6" /></div><h2 className="display-font mt-6 text-3xl">Your request is on its way.</h2><p className="mx-auto mt-3 max-w-md text-sm leading-6 text-[hsl(var(--muted-foreground))]">A team member will follow up using your chosen contact method. Keep your reference safe if one was shown.</p><Button href="/" variant="secondary" testId="button-connect-home">Return home</Button></div> : <form onSubmit={event => { event.preventDefault(); create.mutate({ data: { requestedRole: role, preferredContact: contact, message } }, { onSuccess: () => setSent(true) }); }} className="space-y-6"><div><p className="mono text-[10px] uppercase tracking-[.2em]">01 / Who would help</p><div className="mt-3 grid gap-2 sm:grid-cols-3">{['A youth worker', 'A health worker', 'Someone to listen'].map(option => <button type="button" key={option} data-testid={`button-role-${option}`} onClick={() => setRole(option)} className={cx('rounded-xl border p-3 text-left text-sm', role === option ? 'border-[hsl(var(--primary))] bg-[hsl(var(--secondary))] font-semibold' : 'border-[hsl(var(--border))]')}>{option}</button>)}</div></div><div><p className="mono text-[10px] uppercase tracking-[.2em]">02 / How to reach you</p><div className="mt-3 grid gap-2 sm:grid-cols-3">{['Text message', 'Phone call', 'Email'].map(option => <button type="button" key={option} data-testid={`button-contact-${option}`} onClick={() => setContact(option)} className={cx('rounded-xl border p-3 text-left text-sm', contact === option ? 'border-[hsl(var(--primary))] bg-[hsl(var(--secondary))] font-semibold' : 'border-[hsl(var(--border))]')}>{option}</button>)}</div></div><label className="block text-sm font-medium"><span className="mb-2 block">Anything you want us to know? <span className="font-normal text-[hsl(var(--muted-foreground))]">Optional</span></span><textarea data-testid="input-support-message" value={message} onChange={e => setMessage(e.target.value)} rows={5} placeholder="You can keep this brief." className="w-full resize-none rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3.5 py-3 text-sm outline-none focus:border-[hsl(var(--ring))]" /></label><Button type="submit" testId="button-submit-support" disabled={create.isPending}>{create.isPending ? 'Sending…' : 'Send request'} <ArrowRight className="h-4 w-4" /></Button>{create.isError && <p className="text-sm text-[hsl(var(--destructive))]">We could not send this yet. Please try again.</p>}</form>}</Card><Card className="h-fit bg-[hsl(var(--secondary)/.55)] p-6"><LockKeyhole className="h-5 w-5 text-[hsl(var(--primary))]" /><h2 className="display-font mt-5 text-2xl">A low-pressure start</h2><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Your message goes to a small coordination team. You can ask questions before sharing anything personal.</p><Link href="/rights" data-testid="link-connect-rights" className="mt-6 inline-flex items-center gap-2 text-sm font-semibold text-[hsl(var(--primary))]">How privacy works <ArrowRight className="h-4 w-4" /></Link></Card></div></Frame></AppShell>;
}

export function ConcernPage() {
  const create = useCreateSafeguardingReport();
  const [done, setDone] = useState<string | null>(null);
  const [form, setForm] = useState({ reporterType: 'Young person', category: 'Safety at home', severity: 'I need help soon', description: '' });
  const update = (key: keyof typeof form, value: string) => setForm(prev => ({ ...prev, [key]: value }));
  return <AppShell><Frame eyebrow="Confidential concern" title="You can tell us what is not safe." description="You can report a concern without creating an account. Share only what feels safe to share."><div className="mx-auto max-w-2xl">{done ? <Card className="p-9 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Check className="h-6 w-6" /></div><h2 className="display-font mt-6 text-3xl">Thank you for telling us.</h2><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">Your reference is</p><p className="mono mt-2 text-2xl text-[hsl(var(--primary))]">{done}</p><p className="mx-auto mt-4 max-w-md text-sm leading-6 text-[hsl(var(--muted-foreground))]">Keep it somewhere private. A trained safeguarding team will review this report.</p><Button href="/" variant="secondary" testId="button-report-home">Return home</Button></Card> : <Card className="p-7 md:p-9"><div className="mb-7 flex gap-3 rounded-xl bg-[hsl(var(--accent)/.24)] p-4 text-sm leading-6"><ShieldAlert className="mt-1 h-5 w-5 shrink-0" /><span>If there is immediate danger, contact emergency services or a trusted adult now.</span></div><form onSubmit={e => { e.preventDefault(); create.mutate({ data: form }, { onSuccess: result => setDone(result.reference) }); }} className="space-y-5"><label className="block text-sm font-medium"><span className="mb-2 block">I am reporting as</span><select data-testid="input-reporter-type" value={form.reporterType} onChange={e => update('reporterType', e.target.value)} className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3.5 py-3"><option>Young person</option><option>Parent or carer</option><option>Professional</option><option>Someone else</option></select></label><label className="block text-sm font-medium"><span className="mb-2 block">What is the concern about?</span><select data-testid="input-concern-category" value={form.category} onChange={e => update('category', e.target.value)} className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3.5 py-3"><option>Safety at home</option><option>Abuse or exploitation</option><option>Someone else’s safety</option><option>Something else</option></select></label><label className="block text-sm font-medium"><span className="mb-2 block">How urgent does it feel?</span><select data-testid="input-concern-severity" value={form.severity} onChange={e => update('severity', e.target.value)} className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3.5 py-3"><option>I need help soon</option><option>I am worried but not in immediate danger</option><option>There is immediate danger</option></select></label><label className="block text-sm font-medium"><span className="mb-2 block">What happened?</span><textarea data-testid="input-concern-description" required value={form.description} onChange={e => update('description', e.target.value)} rows={7} className="w-full resize-none rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] px-3.5 py-3" placeholder="Include what you know, where it happened, and when." /></label><Button type="submit" variant="danger" testId="button-submit-concern" disabled={create.isPending}>{create.isPending ? 'Submitting securely…' : 'Submit confidential report'}</Button>{create.isError && <p className="text-sm text-[hsl(var(--destructive))]">We could not submit this report. Please try again.</p>}</form></Card>}</div></Frame></AppShell>;
}

export function RightsPage() {
  return <AppShell><Frame eyebrow="Your rights" title="You deserve to know what happens next." description="A plain-language guide to choice, privacy, and when someone may need to act to keep you safe."><div className="grid gap-5 md:grid-cols-2">{[['You choose the pace', 'You can browse without an account, pause a self-check, or decide not to share more.'], ['Privacy is the default', 'We only ask for what is needed for the next step. Staff see pseudonymous references where possible.'], ['Consent stays visible', 'Before a request is passed to a person or service, you should understand what will happen and why.'], ['Safety can change the plan', 'If someone may be in serious danger, trained staff may need to act. They will explain this wherever it is safe to do so.']].map(([title, body], index) => <Card key={title} className="p-7"><div className="grid h-9 w-9 place-items-center rounded-full bg-[hsl(var(--secondary))] font-mono text-xs text-[hsl(var(--primary))]">0{index + 1}</div><h2 className="display-font mt-7 text-2xl">{title}</h2><p className="mt-3 text-sm leading-7 text-[hsl(var(--muted-foreground))]">{body}</p></Card>)}</div><Card className="mt-7 flex flex-col gap-5 bg-[hsl(var(--primary))] p-7 text-[hsl(var(--primary-foreground))] md:flex-row md:items-center md:justify-between"><div><h2 className="display-font text-2xl">Still have a question?</h2><p className="mt-2 text-sm opacity-70">Ask a person rather than guessing.</p></div><Button href="/connect" variant="secondary" testId="button-rights-connect">Talk to someone</Button></Card></Frame></AppShell>;
}

export function LoginPage() {
  const login = useLogin();
  const [, setLocation] = useLocation();
  const [email, setEmail] = useState('admin@yconnect.test');
  const [password, setPassword] = useState('Password123!');
  return <AppShell><div className="mx-auto grid min-h-[calc(100dvh-74px)] max-w-7xl items-center gap-12 px-5 py-12 lg:grid-cols-2 lg:px-10"><div><p className="mono text-[10px] uppercase tracking-[.2em] text-[hsl(var(--primary)/.72)]">Staff workspace</p><h1 className="display-font mt-5 text-5xl leading-[1.05] text-[hsl(var(--primary))]">Good coordination makes room for care.</h1><p className="mt-5 max-w-lg text-base leading-7 text-[hsl(var(--muted-foreground))]">A clear operational view for teams supporting young people with discretion.</p></div><Card className="mx-auto w-full max-w-md p-7 md:p-9"><h2 className="display-font text-3xl">Sign in</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Use a synthetic staff account for this prototype.</p><form className="mt-8 space-y-5" onSubmit={e => { e.preventDefault(); login.mutate({ data: { email, password } }, { onSuccess: () => setLocation('/dashboard') }); }}><Input label="Work email" name="email" type="email" value={email} onChange={setEmail} required /><Input label="Password" name="password" type="password" value={password} onChange={setPassword} required /><Button type="submit" testId="button-login" disabled={login.isPending}>{login.isPending ? 'Signing in…' : 'Open workspace'} <ArrowRight className="h-4 w-4" /></Button>{login.isError && <p className="text-sm text-[hsl(var(--destructive))]">Those details did not work. Try the prototype account or ask an administrator.</p>}</form></Card></div></AppShell>;
}

function StaffFrame({ children, ...props }: ComponentProps<typeof Frame>) { return <AppShell staff><Frame {...props}>{children}</Frame></AppShell>; }
function TableShell({ children }: { children: ReactNode }) { return <div className="overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] shadow-[var(--shadow-xs)]"><div className="overflow-x-auto">{children}</div></div>; }
function Table({ headers, rows, empty = 'Nothing to show yet.' }: { headers: string[]; rows: ReactNode[][]; empty?: string }) { return rows.length === 0 ? <EmptyState title="Queue is clear" body={empty} /> : <TableShell><table className="w-full min-w-[720px] text-left text-sm"><thead className="bg-[hsl(var(--muted)/.55)] text-[11px] uppercase tracking-wider text-[hsl(var(--muted-foreground))]"><tr>{headers.map(header => <th key={header} className="px-5 py-4 font-medium">{header}</th>)}</tr></thead><tbody className="divide-y divide-[hsl(var(--border))]">{rows.map((row, i) => <tr key={i} className="transition hover:bg-[hsl(var(--muted)/.3)]">{row.map((cell, j) => <td key={j} className="px-5 py-4 align-middle">{cell}</td>)}</tr>)}</tbody></table></TableShell>; }

export function DashboardPage() {
  const { data, isLoading, isError } = useGetDashboardSummary();
  const current = useGetCurrentUser();
  return <StaffFrame eyebrow="Operations / overview" title={`Good morning${current.data?.name ? `, ${current.data.name.split(' ')[0]}` : ''}.`} description="A calm view of what needs attention, what moved, and what can wait."><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{(data?.metrics ?? []).map(metric => <Link href={metric.href} data-testid={`card-metric-${metric.label}`} key={metric.label}><Card className="h-full p-5 transition hover:-translate-y-0.5"><div className="flex items-start justify-between"><p className="text-sm text-[hsl(var(--muted-foreground))]">{metric.label}</p><ArrowRight className="h-4 w-4 text-[hsl(var(--primary)/.6)]" /></div><p className="mt-6 display-font text-4xl text-[hsl(var(--primary))]">{metric.value}</p><p className="mt-2 text-xs text-[hsl(var(--muted-foreground))]">{metric.detail}</p></Card></Link>)}</div>{isLoading ? <LoadingState /> : isError ? <ErrorState /> : <div className="mt-8 grid gap-6 lg:grid-cols-[1.2fr_.8fr]"><Card className="p-6"><div className="flex items-center justify-between"><div><p className="mono text-[10px] uppercase tracking-[.2em]">Recent movement</p><h2 className="display-font mt-2 text-2xl">The work behind the numbers</h2></div><Link href="/audit" data-testid="link-dashboard-audit" className="text-sm font-semibold text-[hsl(var(--primary))]">View audit</Link></div><div className="mt-7 space-y-1">{(data?.recentActivity ?? []).length === 0 ? <EmptyState title="A quiet start" body="New activity will appear here." /> : (data?.recentActivity ?? []).map(item => <div key={item.id} data-testid={`activity-${item.id}`} className="flex gap-4 border-b border-[hsl(var(--border))] py-4 last:border-0"><div className="mt-1 h-2 w-2 shrink-0 rounded-full bg-[hsl(var(--sidebar-primary))]" /><div className="flex-1"><p className="text-sm">{item.text}</p><p className="mt-1 mono text-[10px] text-[hsl(var(--muted-foreground))]">{item.time}</p></div></div>)}</div></Card><Card className="p-6"><p className="mono text-[10px] uppercase tracking-[.2em]">Notifications</p><h2 className="display-font mt-2 text-2xl">Keep in view</h2><div className="mt-6 space-y-3">{(data?.notifications ?? []).length === 0 ? <EmptyState title="All caught up" body="No new notes from your workspace." /> : (data?.notifications ?? []).map(note => <div key={note.id} className={cx('rounded-xl p-4', note.unread ? 'bg-[hsl(var(--accent)/.24)]' : 'bg-[hsl(var(--muted)/.55)]')}><div className="flex items-center justify-between gap-3"><p className="text-sm font-semibold">{note.title}</p>{note.unread && <span className="h-2 w-2 rounded-full bg-[hsl(var(--destructive))]" />}</div><p className="mt-1 text-xs leading-5 text-[hsl(var(--muted-foreground))]">{note.body}</p></div>)}</div></Card></div>}</StaffFrame>;
}

export function CasesPage() {
  const { data, isLoading, isError } = useListCases();
  const [search, setSearch] = useState('');
  const cases = (data ?? []).filter(item => `${item.caseRef} ${item.alias} ${item.district}`.toLowerCase().includes(search.toLowerCase()));
  return <StaffFrame eyebrow="Operations / cases" title="Pseudonymous cases" description="A focused list for coordination. Keep identities out of notes and use the case reference in conversations." action={<Button href="/referrals/new" testId="button-new-referral"><Plus className="h-4 w-4" />New referral</Button>}><div className="mb-5 flex max-w-sm items-center gap-2 rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-3"><Search className="h-4 w-4 text-[hsl(var(--muted-foreground))]" /><input data-testid="input-case-search" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search reference or alias" className="w-full bg-transparent py-3 text-sm outline-none" /></div>{isLoading ? <LoadingState /> : isError ? <ErrorState /> : <Table headers={['Reference', 'Alias', 'District', 'Status', 'Risk', 'Assigned to']} rows={cases.map(item => [<Link href={`/followup?case=${item.id}`} data-testid={`link-case-${item.id}`} className="mono font-medium text-[hsl(var(--primary))]">{item.caseRef}</Link>, item.alias, item.district, <Pill tone={item.status.toLowerCase().includes('open') ? 'good' : 'neutral'}>{item.status}</Pill>, <Pill tone={item.riskLevel.toLowerCase().includes('high') ? 'risk' : 'warn'}>{item.riskLevel}</Pill>, item.assignedTo])} empty="New pseudonymous cases will appear when a person asks for support." />}</StaffFrame>;
}

export function FollowupsPage() {
  const { data, isLoading, isError } = useListFollowups();
  const complete = useCompleteFollowup();
  const queryClient = useQueryClient();
  const tasks = data ?? [];
  return <StaffFrame eyebrow="Operations / follow-up" title="Follow-up, without losing the thread." description="See what is due, record barriers, and make the next option visible." action={<Button href="/followup/new" testId="button-new-followup"><Plus className="h-4 w-4" />Add follow-up</Button>}>{isLoading ? <LoadingState /> : isError ? <ErrorState /> : <Table headers={['Case', 'Task', 'Due', 'Owner', 'Status', '']} rows={tasks.map(task => [<Link href={`/followup/${task.id}`} data-testid={`link-followup-${task.id}`} className="font-medium text-[hsl(var(--primary))]">{task.caseRef}<span className="block text-xs font-normal text-[hsl(var(--muted-foreground))]">{task.alias}</span></Link>, task.type, <span className={task.overdue ? 'font-semibold text-[hsl(var(--destructive))]' : ''}>{formatDate(task.dueDate)}{task.overdue && <span className="ml-2 text-[10px] uppercase">Overdue</span>}</span>, task.assignedTo, <Pill tone={task.status.toLowerCase().includes('complete') ? 'good' : task.overdue ? 'risk' : 'warn'}>{task.status}</Pill>, task.status.toLowerCase().includes('complete') ? <Check className="h-4 w-4 text-[hsl(var(--primary))]" /> : <Button variant="quiet" testId={`button-complete-followup-${task.id}`} onClick={() => complete.mutate({ id: task.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListFollowupsQueryKey() }) })}>Complete</Button>])} empty="Nothing due. That can be a good thing." />}</StaffFrame>;
}

export function FollowupDetailPage() {
  const { id = '' } = useParams<{ id: string }>();
  const numericId = Number(id);
  const { data, isLoading, isError } = useGetFollowup(numericId, { query: { enabled: Boolean(numericId), queryKey: getGetFollowupQueryKey(numericId) } });
  const update = useUpdateFollowupBarrier();
  const [barrier, setBarrier] = useState('');
  const [pathway, setPathway] = useState('');
  return <StaffFrame eyebrow="Follow-up / detail" title={data ? `${data.caseRef} · ${data.type}` : 'Follow-up detail'} description="Record what got in the way, then make the alternative pathway concrete.">{isLoading ? <LoadingState /> : isError || !data ? <ErrorState /> : <div className="grid gap-6 lg:grid-cols-[1fr_320px]"><Card className="p-7"><div className="flex flex-wrap gap-2"><Pill>{data.status}</Pill>{data.overdue && <Pill tone="risk">Overdue</Pill>}</div><h2 className="display-font mt-7 text-3xl">{data.alias}</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Due {formatDate(data.dueDate)} · assigned to {data.assignedTo}</p><div className="mt-9 grid gap-5"><label className="text-sm font-medium">What barrier came up?<textarea data-testid="input-followup-barrier" rows={4} value={barrier || data.barrier} onChange={e => setBarrier(e.target.value)} className="mt-2 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] p-3" /></label><label className="text-sm font-medium">Alternative pathway<textarea data-testid="input-followup-pathway" rows={4} value={pathway || data.alternativePathway} onChange={e => setPathway(e.target.value)} className="mt-2 w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] p-3" /></label><Button testId="button-save-barrier" disabled={update.isPending} onClick={() => update.mutate({ id: data.id, data: { barrier, alternativePathway: pathway } })}>{update.isPending ? 'Saving…' : 'Save note'} <Check className="h-4 w-4" /></Button></div></Card><Card className="h-fit bg-[hsl(var(--secondary)/.55)] p-6"><p className="mono text-[10px] uppercase tracking-[.2em]">Careful handoff</p><p className="display-font mt-4 text-2xl">The barrier is useful data.</p><p className="mt-3 text-sm leading-6 text-[hsl(var(--muted-foreground))]">It helps the next person offer something that fits rather than asking the same question again.</p></Card></div>}</StaffFrame>;
}

export function FollowupCreatePage() {
  const create = useCreateFollowup();
  const cases = useListCases();
  const [, setLocation] = useLocation();
  const [caseId, setCaseId] = useState(String(cases.data?.[0]?.id ?? ''));
  const [type, setType] = useState('Check-in');
  const [dueDate, setDueDate] = useState('');
  return <StaffFrame eyebrow="Follow-up / new task" title="Add a follow-up" description="Give the next contact a clear purpose and a realistic due date."><Card className="max-w-2xl p-7"><form className="space-y-5" onSubmit={event => { event.preventDefault(); create.mutate({ data: { caseId: Number(caseId), type, dueDate } }, { onSuccess: result => setLocation(`/followup/${result.id}`) }); }}><label className="block text-sm font-medium"><span className="mb-2 block">Case</span><select data-testid="input-followup-case" value={caseId} onChange={e => setCaseId(e.target.value)} className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] p-3">{(cases.data ?? []).map(item => <option key={item.id} value={item.id}>{item.caseRef} · {item.alias}</option>)}</select></label><Input label="Task type" name="followup-type" value={type} onChange={setType} placeholder="e.g. Check-in" required /><Input label="Due date" name="followup-due-date" type="date" value={dueDate} onChange={setDueDate} required /><Button type="submit" testId="button-submit-followup" disabled={create.isPending}>{create.isPending ? 'Adding…' : 'Add follow-up'} <ArrowRight className="h-4 w-4" /></Button>{create.isError && <p className="text-sm text-[hsl(var(--destructive))]">We could not add this task. Try again.</p>}</form></Card></StaffFrame>;
}

export function ReferralsPage() {
  const { data, isLoading, isError } = useListReferrals();
  const advance = useAdvanceReferral();
  const queryClient = useQueryClient();
  return <StaffFrame eyebrow="Operations / referrals" title="Referral pipeline" description="Move requests forward with enough context for the receiving service to respond well." action={<Button href="/referrals/new" testId="button-create-referral"><Plus className="h-4 w-4" />Create referral</Button>}>{isLoading ? <LoadingState /> : isError ? <ErrorState /> : <Table headers={['Case', 'Target service', 'Service point', 'Status', 'Started', '']} rows={(data ?? []).map(item => [<Link href={`/referrals/${item.id}`} data-testid={`link-referral-${item.id}`} className="font-medium text-[hsl(var(--primary))]">{item.caseRef}</Link>, item.targetService, item.servicePoint || 'Not assigned', <Pill tone={item.status.toLowerCase().includes('complete') ? 'good' : 'warn'}>{item.status}</Pill>, formatDate(item.initiatedAt), <Button variant="quiet" testId={`button-advance-referral-${item.id}`} onClick={() => advance.mutate({ id: item.id, data: { status: item.status === 'open' ? 'in_progress' : 'complete' } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListReferralsQueryKey() }) })}>Advance <ArrowRight className="h-3.5 w-3.5" /></Button>])} empty="When a person is referred to a service, the handoff will live here." />}</StaffFrame>;
}

export function ReferralDetailPage() {
  const { id } = useParams<{ id: string }>();
  const { data } = useListReferrals();
  const item = (data ?? []).find(referral => referral.id === Number(id));
  return <StaffFrame eyebrow="Referrals / detail" title={item ? `${item.caseRef} referral` : 'Create a referral'} description="Keep the reason for a referral clear, respectful, and useful to the receiving team."><Card className="max-w-2xl p-7"><ReferralForm existing={item} /></Card></StaffFrame>;
}
function ReferralForm({ existing }: { existing?: any }) {
  const create = useCreateReferral();
  const cases = useListCases();
  const [caseId, setCaseId] = useState(existing?.caseId ?? cases.data?.[0]?.id ?? 0);
  const [target, setTarget] = useState(existing?.targetService ?? '');
  const [reason, setReason] = useState(existing?.reason ?? '');
  const [, setLocation] = useLocation();
  return <form className="space-y-5" onSubmit={e => { e.preventDefault(); create.mutate({ data: { caseId: Number(caseId), targetService: target, reason } }, { onSuccess: result => setLocation(`/referrals/${result.id}`) }); }}><label className="block text-sm font-medium"><span className="mb-2 block">Case</span><select data-testid="input-referral-case" value={caseId} onChange={e => setCaseId(Number(e.target.value))} className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] p-3">{(cases.data ?? []).map(item => <option key={item.id} value={item.id}>{item.caseRef} · {item.alias}</option>)}</select></label><Input label="Target service" name="target-service" value={target} onChange={setTarget} placeholder="e.g. adolescent health clinic" required /><label className="block text-sm font-medium"><span className="mb-2 block">Reason for referral</span><textarea data-testid="input-referral-reason" required value={reason} onChange={e => setReason(e.target.value)} rows={5} className="w-full rounded-xl border border-[hsl(var(--input))] bg-[hsl(var(--background))] p-3" /></label><Button type="submit" testId="button-submit-referral" disabled={create.isPending}>{create.isPending ? 'Creating…' : 'Create referral'} <ArrowRight className="h-4 w-4" /></Button></form>;
}

export function EidPage() {
  const { data, isLoading, isError } = useListEidPairs();
  return <StaffFrame eyebrow="Operations / EID" title="Mother–infant pairs" description="A milestone view for early infant diagnosis coordination, with the next due action always close at hand."><div className="grid gap-4 md:grid-cols-2">{isLoading ? <LoadingState /> : isError ? <ErrorState /> : (data ?? []).length === 0 ? <EmptyState title="No pairs in this view" body="New pair records will appear after enrolment." /> : (data ?? []).map(pair => <Link href={`/eid/${pair.id}`} data-testid={`card-eid-${pair.id}`} key={pair.id}><Card className="p-6 transition hover:-translate-y-0.5"><div className="flex items-start justify-between"><div><p className="mono text-xs text-[hsl(var(--primary))]">{pair.motherRef} · {pair.infantRef}</p><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">{pair.district}</p></div><Pill tone={pair.progress > 70 ? 'good' : 'warn'}>{pair.progress}% complete</Pill></div><div className="mt-7 h-2 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><div className="h-full rounded-full bg-[hsl(var(--sidebar-primary))]" style={{ width: `${pair.progress}%` }} /></div><p className="mt-4 text-sm"><span className="text-[hsl(var(--muted-foreground))]">Next due · </span>{formatDate(pair.nextDue)}</p></Card></Link>)}</div></StaffFrame>;
}

export function EidDetailPage() {
  const { id = '' } = useParams<{ id: string }>();
  const numericId = Number(id);
  const { data, isLoading, isError } = useGetEidPair(numericId, { query: { enabled: Boolean(numericId), queryKey: getGetEidPairQueryKey(numericId) } });
  const complete = useCompleteEidMilestone();
  return <StaffFrame eyebrow="EID / timeline" title={data ? `${data.motherRef} · ${data.infantRef}` : 'EID timeline'} description="Record milestone outcomes without losing the human sequence behind the checklist.">{isLoading ? <LoadingState /> : isError || !data ? <ErrorState /> : <Card className="p-7"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[hsl(var(--border))] pb-6"><div><p className="text-sm text-[hsl(var(--muted-foreground))]">{data.district}</p><p className="display-font mt-2 text-3xl">{data.progress}% complete</p></div><Pill tone="good">Next due {formatDate(data.nextDue)}</Pill></div><div className="mt-7 space-y-3">{data.milestones.map(milestone => <div key={milestone.id} className="flex items-center gap-4 rounded-xl border border-[hsl(var(--border))] p-4"><div className={cx('grid h-9 w-9 shrink-0 place-items-center rounded-full', milestone.status.toLowerCase().includes('complete') ? 'bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]' : 'bg-[hsl(var(--muted))]')}><Check className="h-4 w-4" /></div><div className="flex-1"><p className="text-sm font-semibold">{milestone.name}</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Due {formatDate(milestone.dueDate)} {milestone.result && `· ${milestone.result}`}</p></div>{!milestone.status.toLowerCase().includes('complete') && <Button variant="quiet" testId={`button-complete-milestone-${milestone.id}`} onClick={() => complete.mutate({ id: milestone.id, data: { result: 'Completed' } })}>Record</Button>}</div>)}</div></Card>}</StaffFrame>;
}

export function ConnectRequestsPage() {
  const { data, isLoading, isError } = useListSupportRequests();
  return <StaffFrame eyebrow="Operations / connection queue" title="Requests for a human" description="A small queue with enough context to respond thoughtfully, not a race to clear a number."><TableShell>{isLoading ? <LoadingState /> : isError ? <ErrorState /> : <Table headers={['Case', 'Requested role', 'Contact preference', 'Status', 'Received']} rows={(data ?? []).map(item => [<span className="mono text-[hsl(var(--primary))]">{item.caseRef}</span>, item.requestedRole, item.preferredContact, <Pill tone={item.status.toLowerCase().includes('open') ? 'warn' : 'good'}>{item.status}</Pill>, formatDate(item.createdAt)])} empty="No one is waiting for a response right now." />}</TableShell></StaffFrame>;
}

export function SafeguardingPage() {
  const { data, isLoading, isError } = useListSafeguardingReports();
  return <StaffFrame eyebrow="Restricted / safeguarding" title="Safeguarding queue" description="Access is limited. Review only what is needed, record the next safe action, and protect the person behind the reference."><div className="mb-6 flex gap-3 rounded-2xl border border-[hsl(var(--destructive)/.24)] bg-[hsl(var(--destructive)/.05)] p-5"><ShieldAlert className="h-5 w-5 shrink-0 text-[hsl(var(--destructive))]" /><p className="text-sm leading-6">This is a restricted workspace. Do not copy case details into personal notes or external tools.</p></div>{isLoading ? <LoadingState /> : isError ? <ErrorState /> : <Table headers={['Reference', 'Reporter', 'Category', 'Severity', 'Status', 'Received']} rows={(data ?? []).map(item => [<span className="mono font-medium text-[hsl(var(--destructive))]">{item.reference}</span>, item.reporterType, item.category, <Pill tone={item.severity.toLowerCase().includes('immediate') ? 'risk' : 'warn'}>{item.severity}</Pill>, <Pill>{item.status}</Pill>, formatDate(item.createdAt)])} empty="No safeguarding reports are waiting for review." />}</StaffFrame>;
}

function MetricGroup({ title, values }: { title: string; values?: Record<string, number> }) {
  const items = Object.entries(values ?? {});
  return <Card className="p-6"><div className="flex items-center justify-between"><h2 className="display-font text-2xl">{title}</h2><FileText className="h-4 w-4 text-[hsl(var(--muted-foreground))]" /></div><div className="mt-6 space-y-3">{items.length === 0 ? <p className="text-sm text-[hsl(var(--muted-foreground))]">No aggregated values yet.</p> : items.map(([key, value]) => <div key={key} className="flex items-center justify-between border-b border-[hsl(var(--border))] pb-3 last:border-0"><span className="text-sm capitalize text-[hsl(var(--muted-foreground))]">{key.replaceAll('_', ' ')}</span><span className="mono text-sm">{value}</span></div>)}</div></Card>;
}
export function ReportsPage() {
  const { data, isLoading, isError } = useGetReports();
  return <StaffFrame eyebrow="Reporting / aggregate" title="See the shape of support." description="De-identified metrics for reflection and planning. Counts are signals, not scorecards.">{isLoading ? <LoadingState /> : isError ? <ErrorState /> : <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3"><MetricGroup title="Assessments" values={data?.assessments} /><MetricGroup title="Referrals" values={data?.referrals} /><MetricGroup title="Follow-ups" values={data?.followups} /><MetricGroup title="EID" values={data?.eid} /><MetricGroup title="Human support" values={data?.supportRequests} /><MetricGroup title="Safeguarding" values={data?.safeguarding} /></div>}</StaffFrame>;
}

export function AuditPage() {
  const { data, isLoading, isError } = useGetAudit();
  return <StaffFrame eyebrow="Governance / audit" title="A clear record of the work." description="Every operational change should be explainable, reviewable, and connected to a role.">{isLoading ? <LoadingState /> : isError ? <ErrorState /> : <Table headers={['Action', 'Entity', 'Actor', 'Time']} rows={(data ?? []).map(item => [<span className="font-medium">{item.action}</span>, item.entity, item.actor, item.time])} empty="No audit entries have been recorded yet." />}</StaffFrame>;
}

export function AdminUsersPage() {
  const { data, isLoading, isError } = useListStaffUsers();
  const create = useCreateStaffUser();
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ name: '', email: '', role: 'coordinator', district: 'Central' });
  return <StaffFrame eyebrow="Administration / access" title="Synthetic staff access" description="Keep roles explicit and access proportionate to the work."><div className="mb-5 flex justify-end"><Button onClick={() => setOpen(true)} testId="button-add-staff"><Plus className="h-4 w-4" />Add staff user</Button></div>{isLoading ? <LoadingState /> : isError ? <ErrorState /> : <Table headers={['Name', 'Email', 'Role', 'District', 'Status']} rows={(data ?? []).map(item => [item.name, item.email, <Pill>{item.roleLabel}</Pill>, item.district, <Pill tone={item.status.toLowerCase().includes('active') ? 'good' : 'neutral'}>{item.status}</Pill>])} empty="No staff accounts have been created." />}{open && <div className="fixed inset-0 z-50 grid place-items-center bg-[hsl(var(--primary)/.35)] p-5"><Card className="w-full max-w-md p-7"><div className="flex items-center justify-between"><h2 className="display-font text-2xl">Add staff user</h2><button data-testid="button-close-staff" onClick={() => setOpen(false)}><X className="h-5 w-5" /></button></div><form className="mt-6 space-y-4" onSubmit={e => { e.preventDefault(); create.mutate({ data: form }, { onSuccess: () => setOpen(false) }); }}><Input label="Name" name="staff-name" value={form.name} onChange={value => setForm({ ...form, name: value })} required /><Input label="Email" name="staff-email" value={form.email} onChange={value => setForm({ ...form, email: value })} required /><Input label="Role" name="staff-role" value={form.role} onChange={value => setForm({ ...form, role: value })} required /><Input label="District" name="staff-district" value={form.district} onChange={value => setForm({ ...form, district: value })} required /><Button type="submit" testId="button-submit-staff" disabled={create.isPending}>{create.isPending ? 'Creating…' : 'Create account'}</Button></form></Card></div>}</StaffFrame>;
}

export function AdminDirectoryPage() {
  const { data, isLoading, isError } = useListServices();
  return <StaffFrame eyebrow="Administration / directory" title="Service directory" description="Review the synthetic service points available to the public directory."><Table headers={['Service point', 'Type', 'District', 'Services', 'Hours']} rows={isLoading || isError ? [] : (data ?? []).map(item => [item.name, item.type, item.district, item.services.join(' · '), item.hours])} empty={isLoading ? 'Loading service points…' : isError ? 'The directory could not be loaded.' : 'No service points have been added.'} />{isLoading && <LoadingState label="Loading service points" />}{isError && <ErrorState />}</StaffFrame>;
}

export function AdminContentPage() {
  const { data, isLoading, isError } = useListContent();
  return <StaffFrame eyebrow="Administration / learning" title="Learning library" description="Review the resources currently visible to people using Y-Connect."><Table headers={['Title', 'Category', 'Format', 'Duration', 'Featured']} rows={isLoading || isError ? [] : (data ?? []).map(item => [item.title, item.category, item.mediaType, item.duration, <Pill tone={item.featured ? 'good' : 'neutral'}>{item.featured ? 'Yes' : 'No'}</Pill>])} empty={isLoading ? 'Loading learning resources…' : isError ? 'The learning library could not be loaded.' : 'No resources have been added.'} />{isLoading && <LoadingState label="Loading learning resources" />}{isError && <ErrorState />}</StaffFrame>;
}